CREATE TEMP TABLE bt_old ON COMMIT DROP AS
SELECT member_id, jsonb_array_length(background_timeline) AS n, background_timeline AS tl FROM public.mp_biography WHERE member_id IN (5053, 5066, 5172, 5183, 5194, 5196, 5200, 5206, 5226, 5227, 5228);

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (5053, 5066, 5172, 5183, 5194, 5196, 5200, 5206, 5226, 5227, 5228)) <> 11 THEN RAISE EXCEPTION 'expected 11 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (5053, 5066, 5172, 5183, 5194, 5196, 5200, 5206, 5226, 5227, 5228) AND background_timeline IS NULL) THEN RAISE EXCEPTION 'an MP to top up has no timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_new n USING (member_id) WHERE md5(b.background_timeline::text) = n.old_md5) <> 11 THEN RAISE EXCEPTION 'a timeline is not the one read at generation (changed since)'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 546 THEN RAISE EXCEPTION 'expected 546 MPs with a timeline before'; END IF;
  IF (SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 6703 THEN RAISE EXCEPTION 'expected 6703 entries before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, background_timeline IS NOT NULL AS had, md5(coalesce(background_timeline::text, '')) AS th
  FROM public.mp_biography b;

UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-11-07'
  FROM bt_new n WHERE b.member_id = n.member_id AND md5(b.background_timeline::text) = n.old_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  kept_wrong integer;
  length_wrong integer;
  matching integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5053, 5066, 5172, 5183, 5194, 5196, 5200, 5206, 5226, 5227, 5228) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  -- Every entry the MP had before is still there, as many times as before.
  SELECT count(*) INTO kept_wrong FROM (
    SELECT o.member_id, e, count(*) AS c FROM bt_old o, jsonb_array_elements(o.tl) e GROUP BY o.member_id, e
  ) x JOIN public.mp_biography b USING (member_id)
   WHERE (SELECT count(*) FROM jsonb_array_elements(b.background_timeline) m WHERE m = x.e) <> x.c;
  SELECT count(*) INTO length_wrong FROM public.mp_biography b JOIN bt_old o USING (member_id) JOIN bt_new n USING (member_id)
   WHERE jsonb_array_length(b.background_timeline) <> n.n;
  SELECT count(*) INTO matching FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-11-07';
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 11 %, earlier entries missing or repeated %, lengths wrong %, rows matching the file %, MPs with a timeline %, entries %',
    changed, changed_outside, kept_wrong, length_wrong, matching, with_timeline, entry_total;
  IF changed <> 11 THEN RAISE EXCEPTION 'expected exactly 11 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 11 changed', changed_outside; END IF;
  IF kept_wrong <> 0 THEN RAISE EXCEPTION '% earlier entries are missing or repeated', kept_wrong; END IF;
  IF length_wrong <> 0 THEN RAISE EXCEPTION '% MPs do not have their old length plus the additions', length_wrong; END IF;
  IF matching <> 11 THEN RAISE EXCEPTION 'expected 11 rows matching the file, got %', matching; END IF;
  IF with_timeline <> 546 THEN RAISE EXCEPTION 'expected 546 MPs with a timeline after, got %', with_timeline; END IF;
  IF entry_total <> 6731 THEN RAISE EXCEPTION 'expected 6731 entries, got %', entry_total; END IF;
END $$;

COMMIT;
